// fetch all customers
const custRes = await api.get('/customers', {});
const delayedCustomers = custRes.items.filter(c => c.order && c.order.status === 'delayed');
const delayedIds = delayedCustomers.map(c => c.id);

// fetch all mails
const mailRes = await api.get('/mails', {});
const complaintMails = mailRes.items.filter(m => m.label === 'complaint' && m.customer_id);
const complaintCustomerIds = new Set(complaintMails.map(m => m.customer_id));

// intersect
const resultIds = delayedIds.filter(id => complaintCustomerIds.has(id));
return resultIds;
